### `verify‑credentials.js`

```js
#!/usr/bin/env node
/**
 * Quick sanity‑check for the credentials defined in .env.test.
 *
 * Usage:
 *   npm install pg aws-sdk @anthropic-ai/sdk stripe axios dotenv
 *   node verify-credentials.js
 *
 * The script prints a concise report – no secret values are ever logged.
 */

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const { Anthropic } = require('@anthropic-ai/sdk');
const Stripe = require('stripe');
const axios = require('axios');

/**
 * Helper – prints coloured status messages.
 */
const log = (msg, status = 'INFO') => {
  const colors = {
    INFO: '\x1b[36m',   // cyan
    OK: '\x1b[32m',     // green
    WARN: '\x1b[33m',   // yellow
    ERR: '\x1b[31m',    // red
    RESET: '\x1b[0m',
  };
  console.log(`${colors[status] || ''}[${status}] ${msg}${colors.RESET}`);
};

/**
 * 1️⃣ DATABASE_URL – PostgreSQL
 */
async function testPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('Missing DATABASE_URL');
  const client = new Client({ connectionString: url });

  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res.rowCount === 1) {
      log('PostgreSQL connection succeeded', 'OK');
    } else {
      throw new Error('Unexpected query result');
    }
  } finally {
    await client.end();
  }
}

/**
 * 2️⃣ AWS credentials – STS getCallerIdentity (no charges)
 */
async function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    throw new Error('Missing AWS_ACCESS_KEY_ID or AWS_SECRET_ACCESS_KEY');
  }

  const sts = new AWS.STS({ apiVersion: '2011-06-15' });
  await sts.getCallerIdentity().promise()
    .then(() => log('AWS STS call succeeded', 'OK'))
    .catch(err => { throw new Error(`AWS error: ${err.message}`); });
}

/**
 * 3️⃣ Anthropic API key – minimal /v1/messages call
 */
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error('Missing ANTHROPIC_API_KEY');

  const client = new Anthropic({ apiKey: key });
  try {
    // Intentionally send an empty prompt – the API will respond with a 400 if the key is okay,
    // but a 401/403 if the key is invalid. We treat any HTTP response (even the 400) as "reachable".
    await client.messages.create({
      model: 'claude-2.0',
      max_tokens: 1,
      messages: [{ role: 'user', content: '' }],
    });
    // The call would actually succeed with a tiny response; we consider that OK.
    log('Anthropic API responded (key appears valid)', 'OK');
  } catch (err) {
    // Anthropic SDK surfaces HTTP status via err.statusCode
    if (err.statusCode === 400) {
      // 400 means the request payload was wrong → key is accepted
      log('Anthropic API returned 400 (key is valid, request malformed)', 'OK');
    } else {
      throw new Error(`Anthropic error: ${err.message}`);
    }
  }
}

/**
 * 4️⃣ Stripe secret key – retrieve account details
 */
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('Missing STRIPE_SECRET_KEY');

  const stripe = Stripe(key);
  try {
    await stripe.accounts.retrieve();
    log('Stripe account retrieved successfully', 'OK');
  } catch (err) {
    throw new Error(`Stripe error: ${err.message}`);
  }
}

/**
 * 5️⃣ Logfire token – send a trivial log event
 */
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('Missing LOGFIRE_TOKEN');

  const endpoint = 'https://logfire-api.com/v1/logs'; // replace with actual Logfire endpoint if known
  try {
    await axios.post(
      endpoint,
      { message: 'credential‑verification‑ping', level: 'debug' },
      { headers: { Authorization: `Bearer ${token}` } }
    );
    log('Logfire ping succeeded', 'OK');
  } catch (err) {
    // A 401/403 indicates a bad token; a 404 may indicate the endpoint is wrong.
    const status = err.response?.status;
    if (status === 401 || status === 403) {
      throw new Error('Logfire token rejected (401/403)');
    } else if (status === 404) {
      log('Logfire endpoint not reachable (404) – token may be valid but URL is wrong', 'WARN');
    } else {
      throw new Error(`Logfire error: ${err.message}`);
    }
  }
}

/**
 * Orchestrator – runs each test sequentially, reporting failures but keeping the process alive.
 */
(async () => {
  const checks = [
    { name: 'PostgreSQL', fn: testPostgres },
    { name: 'AWS STS', fn: testAWS },
    { name: 'Anthropic', fn: testAnthropic },
    { name: 'Stripe', fn: testStripe },
    { name: 'Logfire', fn: testLogfire },
  ];

  for (const { name, fn } of checks) {
    try {
      await fn();
    } catch (e) {
      log(`${name} check failed – ${e.message}`, 'ERR');
    }
  }

  log('Credential verification run complete', 'INFO');
})();
```

