## 5️⃣ Putting it all together – Revised `app.js`

Below is a **minimal but production‑ready skeleton** incorporating the above recommendations. You can copy‑paste it, then tailor the whitelist, rate limits, etc., to your needs.

```js
// ----------------------------------------------------------
// app.js – secure, robust Express starter
// ----------------------------------------------------------

// Load environment vars (PORT, NODE_ENV, etc.)
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const errorHandler = require('./errorHandler'); // <-- put the middleware from above in ./errorHandler.js
const asyncHandler = require('./utils/asyncHandler');

const app = express();

// ----------------------------------------------------------
// 1️⃣ Basic security hardening
// ----------------------------------------------------------
app.disable('x-powered-by');               // hide framework details
app.use(helmet());                         // sets a collection of secure headers
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      // add more directives if you serve HTML/JS/CSS
    },
  })
);

// ----------------------------------------------------------
// 2️⃣ CORS (adjust whitelist for your front‑ends)
// ----------------------------------------------------------
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow non‑browser requests (like curl, Postman) with no origin header
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
  })
);

// ----------------------------------------------------------
// 3️⃣ Rate limiting (adjust limits per your traffic)
// ----------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----------------------------------------------------------
// 4️⃣ Body parsing (only needed when you accept POST/PUT)
// ----------------------------------------------------------
app.use(express.json({ limit: '10kb' }));   // reject huge payloads
app.use(express.urlencoded({ extended: false }));

// ----------------------------------------------------------
// 5️⃣ Request logging (only in dev, or pipe to a safe logger)
// ----------------------------------------------------------
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// ----------------------------------------------------------
// 6️⃣ Routes
// ----------------------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // In a real app, replace the static array with a DB call
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  })
);

// ----------------------------------------------------------
// 7️⃣ Centralised error handling (must be after routes)
// ----------------------------------------------------------
app.use(errorHandler);

// ----------------------------------------------------------
// 8️⃣ Server start
// ----------------------------------------------------------
const PORT = process.env.PORT || 3000;

// Graceful shutdown helpers
function shutdown(signal) {
  console.info(`🛑 Received ${signal}. Closing server...`);
  server.close(() => {
    console.info('💡 Server closed. Exiting process.');
    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Catch async errors that escape Express (Node >= 15)
process.on('unhandledRejection', (reason) => {
  console.error('⚠️ Unhandled Promise Rejection:', reason);
});
process.on('uncaughtException', (err) => {
  console.error('💥 Uncaught Exception:', err);
  process.exit(1);
});

const server = app.listen(PORT, () => {
  console.info(`🚀 Server running on http${process.env.NODE_ENV === 'production' ? 's' : ''}://localhost:${PORT}`);
});

module.exports = app;
```

**What changed?**

| Change | Reason |
|--------|--------|
| `dotenv` | Keeps secrets/port out of source control |
| `helmet` + CSP | Sets many HTTP security headers automatically |
| `app.disable('x-powered-by')` | Hides Express version |
| `cors` with whitelist | Prevents unwanted origins from calling the API |
| `express-rate-limit` | Basic DoS mitigation |
| `express.json({limit:'10kb'})` | Rejects overly large bodies (resource‑exhaustion) |
| `morgan` (dev only) | Structured request logging without leaking secrets |
| `asyncHandler` wrapper | Guarantees async errors flow to `errorHandler` |
| Central `errorHandler` middleware | Consistent error response, no stack traces in prod |
| Graceful shutdown + process listeners | Avoids hanging sockets / corrupted state on crashes |
| Use of `process.env.PORT` | Makes the app portable (e.g., Docker, Heroku) |

