```js
#!/usr/bin/env node
/**
 * Quick sanity‑check for the credentials stored in .env.test.
 *
 *  • PostgreSQL connection (uses the native pg driver)
 *  • AWS STS GetCallerIdentity (requires only the access key ID & secret)
 *  • Anthropic health endpoint (GET /v1/models)
 *  • Stripe Account Retrieve (GET /v1/account)
 *  • Logfire ping (GET /ping – adjust if your provider uses a different path)
 *
 * The script prints a short PASS/FAIL line for each credential.
 *
 * ──► Run:
 *   npm install pg node-fetch@2 aws-sdk stripe
 *   node verify-creds.js
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const fetch = require('node-fetch'); // v2 API (commonjs)
const AWS = require('aws-sdk');
const Stripe = require('stripe');

// ------------------------------------------------------------------
// Helper to format output
// ------------------------------------------------------------------
function report(name, ok, details = '') {
  const status = ok ? '✅ PASS' : '❌ FAIL';
  console.log(`${status} – ${name}${details ? ` – ${details}` : ''}`);
}

// ------------------------------------------------------------------
// 1️⃣ PostgreSQL
// ------------------------------------------------------------------
async function testPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return report('PostgreSQL', false, 'DATABASE_URL not set');

  const client = new Client({ connectionString: url });
  try {
    await client.connect();
    // A cheap, read‑only query
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0].ok === 1) {
      report('PostgreSQL', true);
    } else {
      report('PostgreSQL', false, 'Unexpected query result');
    }
  } catch (err) {
    report('PostgreSQL', false, err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

// ------------------------------------------------------------------
// 2️⃣ AWS – STS GetCallerIdentity (no permissions needed beyond the keys)
// ------------------------------------------------------------------
async function testAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return report('AWS', false, 'Access key/secret missing');
  }

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    // Optionally set a region; STS works globally
    region: 'us-east-1',
    // Timeout so the script never hangs forever
    httpOptions: { timeout: 5000 },
  });

  try {
    const data = await sts.getCallerIdentity().promise();
    // If we received a response, the credentials are at least syntactically valid
    report('AWS', true, `ARN: ${data.Arn}`);
  } catch (err) {
    report('AWS', false, err.message);
  }
}

// ------------------------------------------------------------------
// 3️⃣ Anthropic – simple “list models” call (public endpoint)
// ------------------------------------------------------------------
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return report('Anthropic', false, 'API key missing');

  const endpoint = 'https://api.anthropic.com/v1/models';
  try {
    const resp = await fetch(endpoint, {
      method: 'GET',
      headers: {
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
      },
      timeout: 5000,
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const body = await resp.json();
    // The body should contain a `data` array with at least one model entry
    if (Array.isArray(body.data) && body.data.length > 0) {
      report('Anthropic', true, `${body.data.length} models`);
    } else {
      report('Anthropic', false, 'Unexpected payload');
    }
  } catch (err) {
    report('Anthropic', false, err.message);
  }
}

// ------------------------------------------------------------------
// 4️⃣ Stripe – Retrieve the connected account (no charges performed)
// ------------------------------------------------------------------
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return report('Stripe', false, 'Secret key missing');

  const stripe = Stripe(key, { apiVersion: '2023-10-16' });

  try {
    const acct = await stripe.accounts.retrieve();
    report('Stripe', true, `Account ID: ${acct.id}`);
  } catch (err) {
    // Stripe SDK wraps errors – pull out the message
    const msg = err?.raw?.message || err.message || 'unknown';
    report('Stripe', false, msg);
  }
}

// ------------------------------------------------------------------
// 5️⃣ Logfire – generic health endpoint (adjust if needed)
// ------------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return report('Logfire', false, 'Token missing');

  const endpoint = 'https://api.logfire.io/ping'; // <-- replace with your actual ping URL if different
  try {
    const resp = await fetch(endpoint, {
      method: 'GET',
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const body = await resp.json();
    // Many providers return {ok:true} or similar; we just check for a successful JSON response
    report('Logfire', true, JSON.stringify(body));
  } catch (err) {
    report('Logfire', false, err.message);
  }
}

// ------------------------------------------------------------------
// Run all checks sequentially (can be parallelised if desired)
// ------------------------------------------------------------------
(async () => {
  console.log('🔎 Verifying credentials from .env.test …\n');
  await testPostgres();
  await testAws();
  await testAnthropic();
  await testStripe();
  await testLogfire();
  console.log('\n✅ Done');
})();
```

