#!/usr/bin/env node
/**
 * verify-creds.js
 *
 * Quick sanity‑check for the synthetic credentials shipped in .env.test.
 * - Tries to open a PostgreSQL connection.
 * - Sends a lightweight request to each provider using its public “ping” endpoint.
 *
 * Run with:  node test/verify-creds.js   (or npx mocha test/verify-creds.js)
 *
 * The script never prints the actual secret values – only success/failure.
 */

require('dotenv').config({ path: '.env.test' }); // load the test env file

const { Client } = require('pg');
const https = require('https');

// ────────────────────────────────────────────────────────────────────────
// Helper: simple GET request returning a Promise
function httpsGet(url, headers = {}) {
  return new Promise((resolve, reject) => {
    const opts = { method: 'GET', headers };
    const req = https.request(url, opts, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => {
        const body = Buffer.concat(chunks).toString();
        resolve({ status: res.statusCode, body });
      });
    });
    req.on('error', reject);
    req.end();
  });
}

// ────────────────────────────────────────────────────────────────────────
// 1️⃣ PostgreSQL test
async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('🔸 DATABASE_URL not set – skipping DB test');
    return;
  }

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    console.log('✅ PostgreSQL connection successful');
  } catch (err) {
    console.log('❌ PostgreSQL connection failed:', err.message);
  } finally {
    await client.end().catch(() => {}); // ignore any further errors
  }
}

// ────────────────────────────────────────────────────────────────────────
// 2️⃣ External API “ping” tests
async function testExternalApis() {
  const tests = [
    {
      name: 'Anthropic',
      // Anthropic has a “List models” endpoint that works with HEAD‑type request; we’ll do a simple GET to /v1/models
      url: 'https://api.anthropic.com/v1/models',
      headerName: 'x-api-key',
      headerValue: process.env.ANTHROPIC_API_KEY,
    },
    {
      name: 'Stripe',
      // Stripe’s “retrieve account” endpoint (GET /v1/account) works with just the secret key
      url: 'https://api.stripe.com/v1/account',
      headerName: 'Authorization',
      headerValue: process.env.STRIPE_SECRET_KEY ? `Bearer ${process.env.STRIPE_SECRET_KEY}` : null,
    },
    {
      name: 'Logfire',
      // Logfire provides a health endpoint – we’ll use a generic “ping” (if unavailable, the request will 404 which still counts as reachable)
      url: 'https://api.logfire.com/v1/health',
      headerName: 'Authorization',
      headerValue: process.env.LOGFIRE_TOKEN ? `Bearer ${process.env.LOGFIRE_TOKEN}` : null,
    },
  ];

  for (const { name, url, headerName, headerValue } of tests) {
    if (!headerValue) {
      console.log(`🔸 ${name} API key not set – skipping`);
      continue;
    }

    try {
      const headers = headerName ? { [headerName]: headerValue } : {};
      const { status } = await httpsGet(url, headers);
      if (status >= 200 && status < 300) {
        console.log(`✅ ${name} API key seems valid (status ${status})`);
      } else {
        console.log(`⚠️ ${name} responded with ${status} – key may be invalid or endpoint restricted`);
      }
    } catch (err) {
      console.log(`❌ ${name} request failed: ${err.message}`);
    }
  }
}

// ────────────────────────────────────────────────────────────────────────
// Run all checks
(async () => {
  console.log('\n=== Credential verification report ===\n');
  await testDatabase();
  await testExternalApis();
  console.log('\n=== Done ===\n');
})();
```

