/**
 * backup-creds.js
 *
 * Reads the disaster‑recovery credentials from .env.test (or the current process env)
 * and POSTs them as JSON to http://localhost:47301/api/dr-backup.
 *
 * Usage:  node scripts/backup-creds.js
