  process.exit(1);
}

/**
 * Helper: use the native fetch if available (Node ≥18), otherwise fall back to node‑fetch.
 */
let fetchFn;
if (typeof fetch === 'function') {
  fetchFn = fetch; // native
} else {
  // eslint-disable-next-line import/no-extraneous-dependencies
  fetchFn = require('node-fetch');
}

/**
 * POST the JSON payload.
 */
(async () => {
  const endpoint = 'http://localhost:47301/api/dr-backup';
  try {
    const response = await fetchFn(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        // OPTIONAL: add a static token or HMAC here if your endpoint requires auth
        // 'X-Backup-Token': process.env.DR_BACKUP_TOKEN,
      },
      body: JSON.stringify(payload),
