// verify-creds.js – quick health‑check for env‑based secrets
// ------------------------------------------------------------

require('dotenv').config({ path: '.env.test' }); // load the test file
const { Client } = require('pg');
const axios = require('axios');

// Helper – pretty‑print result
const logResult = (name, ok, details = '') => {
  const status = ok ? '✅ SUCCESS' : '❌ FAILURE';
  console.log(`${status} – ${name}${details ? ': ' + details : ''}`);
};

// ------------------------------------------------------------
// 1️⃣ Database (Postgres) connectivity test
// ------------------------------------------------------------
async function testDatabase() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    logResult('Postgres DB', false, 'DATABASE_URL not defined');
    return;
  }

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    // A cheap query that works on any DB
    const res = await client.query('SELECT NOW()');
    logResult('Postgres DB', true, `server time = ${res.rows[0].now}`);
  } catch (err) {
    logResult('Postgres DB', false, err.message);
  } finally {
    await client.end().catch(() => {}); // ignore close errors
  }
}

// ------------------------------------------------------------
// 2️⃣ AWS credentials – simple STS GetCallerIdentity call
// ------------------------------------------------------------
async function testAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    logResult('AWS credentials', false, 'Missing key/secret');
    return;
  }

  // We use the AWS SDK v3 (lighter) – you can install it with:
//   npm install @aws-sdk/client-sts
  const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');

  const sts = new STSClient({
    credentials: {
      accessKeyId: AWS_ACCESS_KEY_ID,
      secretAccessKey: AWS_SECRET_ACCESS_KEY,
    },
    // No region needed for STS GetCallerIdentity, but a placeholder helps the SDK
    region: 'us-east-1',
  });

  try {
    const data = await sts.send(new GetCallerIdentityCommand({}));
    logResult('AWS credentials', true, `ARN = ${data.Arn}`);
  } catch (err) {
    logResult('AWS credentials', false, err.message);
  }
}

// ------------------------------------------------------------
// 3️⃣ Anthropic API key – simple /v1/models list request
// ------------------------------------------------------------
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    logResult('Anthropic API key', false, 'Missing ANTHROPIC_API_KEY');
    return;
  }

  try {
    const resp = await axios.post(
      'https://api.anthropic.com/v1/models',
      {}, // empty body – endpoint just returns the list
      {
        headers: {
          'x-api-key': key,
          'content-type': 'application/json',
        },
        timeout: 5000,
      }
    );
    if (resp.status === 200 && Array.isArray(resp.data.models)) {
      logResult('Anthropic API key', true, `${resp.data.models.length} models`);
    } else {
      logResult('Anthropic API key', false, `Unexpected response`);
    }
  } catch (err) {
    logResult('Anthropic API key', false, err.response?.data?.error?.message || err.message);
  }
}

// ------------------------------------------------------------
// 4️⃣ Stripe secret key – retrieve account information
// ------------------------------------------------------------
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    logResult('Stripe secret key', false, 'Missing STRIPE_SECRET_KEY');
    return;
  }

  try {
    const resp = await axios.get('https://api.stripe.com/v1/account', {
      auth: {
        username: key,
        password: '',
      },
      timeout: 5000,
    });
    if (resp.status === 200 && resp.data.id) {
      logResult('Stripe secret key', true, `Account ID = ${resp.data.id}`);
    } else {
      logResult('Stripe secret key', false, 'Unexpected response');
    }
  } catch (err) {
    const msg = err.response?.data?.error?.message || err.message;
    logResult('Stripe secret key', false, msg);
  }
}

// ------------------------------------------------------------
// 5️⃣ Logfire token – simple ping (Logfire currently offers a
//     health endpoint at https://api.logfire.dev/v1/ping)
// ------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    logResult('Logfire token', false, 'Missing LOGFIRE_TOKEN');
    return;
  }

  try {
    const resp = await axios.get('https://api.logfire.dev/v1/ping', {
      headers: {
        Authorization: `Bearer ${token}`,
      },
      timeout: 5000,
    });
    if (resp.status === 200 && resp.data?.status === 'ok') {
      logResult('Logfire token', true);
    } else {
      logResult('Logfire token', false, 'Unexpected response');
    }
  } catch (err) {
    logResult('Logfire token', false, err.message);
  }
}

// ------------------------------------------------------------
// Main runner
// ------------------------------------------------------------
(async () => {
  console.log('🔎 Starting credential verification …\n');

  await Promise.all([
    testDatabase(),
    testAws(),
    testAnthropic(),
    testStripe(),
    testLogfire(),
  ]);

  console.log('\n🏁 Done.');
})();
```

