  // 5️⃣ Logfire token
  if (process.env.LOGFIRE_TOKEN) {
    results.logfire = await checkLogfire(process.env.LOGFIRE_TOKEN);
  } else {
    results.logfire = { ok: false, error: 'LOGFIRE_TOKEN not set' };
  }

  // -------------------------------------------------
  // Pretty‑print the outcome
  // -------------------------------------------------
  const pad = s => s.padEnd(12);
  console.log('RESULTS');
  console.log('-------');
  for (const [key, info] of Object.entries(results)) {
    const status = info.ok ? '✅ SUCCESS' : `❌ FAILURE`;
