// ---------------------------------------------------------------------------
//  app.js – secure, production‑ready Express skeleton
// ---------------------------------------------------------------------------

require('dotenv').config();               // 1️⃣ Load env vars from .env (never commit secrets)
const express = require('express');
const helmet = require('helmet');         // 2️⃣ Secure HTTP headers
const rateLimit = require('express-rate-limit'); // 3️⃣ Basic DoS protection
const { errors: celebrateErrors } = require('celebrate'); // 4️⃣ Celebrate = Joi validation
const morgan = require('morgan');         // Optional: request logging (use in dev only)
const asyncHandler = require('express-async-handler'); // 5️⃣ Auto‑catch async errors

const app = express();

// ---------------------------------------------------------------------------
// Middleware stack
// ---------------------------------------------------------------------------

// 2️⃣ Helmet – set a sensible default security header set
app.use(helmet());

// 3️⃣ Rate limiting – 100 requests per 15 min per IP (tune for your use‑case)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing (JSON only – reject large payloads early)
app.use(express.json({ limit: '100kb' })); // 6️⃣ Prevent huge bodies

// Optional: detailed request logs in development
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// ---------------------------------------------------------------------------
// Helper – generic success responder (helps keep a consistent shape)
// ---------------------------------------------------------------------------
const ok = (data) => ({ status: 'ok', timestamp: new Date().toISOString(), data });

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

app.get(
  '/health',
  asyncHandler(async (req, res) => {
    // No user input – just a simple health check.
    res.json(ok({ uptime: process.uptime() }));
  })
);

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // In a real app you’d fetch from DB & possibly filter/paginate.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(ok(users));
  })
);

// ---------------------------------------------------------------
// Example of a **validated** endpoint (demonstrates pattern)
// ---------------------------------------------------------------
const { celebrate, Joi } = require('celebrate');

app.post(
  '/users',
  celebrate({
    body: Joi.object({
      name: Joi.string().trim().min(2).max  (50).required(),
      email: Joi.string().email().required(),
    }),
  }),
  asyncHandler(async (req, res) => {
    // Pretend we inserted into a DB and got an ID:
    const newUser = { id: Date.now(), ...req.body };
    // Respond with 201 Created + location header
    res.status(201).location(`/users/${newUser.id}`).json(ok(newUser));
  })
);

// ---------------------------------------------------------------------------
// Validation error formatter (celebrate → nice JSON)
// ---------------------------------------------------------------------------
app.use(celebrateErrors((err, req, res, next) => {
  // Strip Joi internals, keep only what we want to expose.
  const details = err.details.map((d) => ({
    message: d.message,
    path: d.path,
  }));
  res.status(400).json({
    status: 'error',
    timestamp: new Date().toISOString(),
    errors: details,
  });
}));

// ---------------------------------------------------------------------------
// Centralized error handler (catch‑all)
// ---------------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full stack in server logs (but never expose to client)
  console.error(err);

  // Differentiate operational vs programming errors if you tag them.
  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;

  res.status(status).json({
    status: 'error',
    timestamp: new Date().toISOString(),
    message,
    // In production you might omit `stack` entirely; include only in dev.
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ---------------------------------------------------------------------------
// Start server – configurable port, graceful shutdown
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`🔹 Server listening on http://0.0.0.0:${PORT}`);
});

// Graceful shutdown (helps with Docker/K8s, CI, etc.)
const shutdown = (signal) => {
  console.log(`\n⚙️  Received ${signal}. Closing HTTP server...`);
  server.close(() => {
    console.log('🛑 HTTP server closed. Exiting process.');
    process.exit(0);
  });
  // Force‑exit if not closed within 10 s
  setTimeout(() => {
    console.error('❗ Forced shutdown after timeout.');
    process.exit(1);
  }, 10_000);
};

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

module.exports = app; // keep export for testing
```

### What changed & why?

| Change | Security / reliability benefit |
|--------|---------------------------------|
| **dotenv + `process.env.PORT`** | Avoids hard‑coded values; you can keep secrets out of source. |
| **helmet** | Sets `Content‑Security‑Policy`, `X‑Frame‑Options`, `X‑Content‑Type‑Options`, etc. |
| **express-rate-limit** | Throttles abusive IPs before they reach business logic. |
| **`express.json({ limit: '100kb' })`** | Limits request size → mitigates DoS via massive payloads. |
| **`express-async-handler`** | Guarantees any async `throw` ends up in the central error handler. |
| **Consistent JSON envelope (`ok`)** | Forces a predictable response shape; easier for clients and audits. |
| **celebrate + Joi validation** | Demonstrates **input validation**. Replace with any validator you prefer. |
| **`celebrateErrors` formatter** | Turns validation failures into clean, non‑leaky JSON (no raw Joi objects). |
| **Central error handler** | Hides stack traces from callers, logs internally, returns consistent error payload. |
| **Graceful shutdown** | Prevents “half‑written” connections when the container is stopped. |
| **Morgan (dev only)** | Logs to console in development; can be swapped for `winston` in prod. |
| **Response codes (`201`, `Location` header)** | Aligns with HTTP semantics – a small security best‑practice (helps clients avoid guessing endpoints). |

---

## 3. Additional “future‑proof” recommendations

| Concern | Recommendation |
|---------|----------------|
| **HTTPS** | In production terminate TLS at a reverse proxy (NGINX, Cloud Load Balancer). Never serve plain HTTP on the public internet. |
| **CORS** | If you expose APIs to browsers, add a strict `cors` config (`origin: 'https://your‑frontend.com'`). |
| **Dependency hygiene** | Run `npm audit` / `npm audit fix` often; lock file (`package-lock.json`) should be committed. |
| **Content‑Security‑Policy** | Helmet’s default CSP is a good start, but tailor it to the assets you actually serve. |
| **Data sanitisation** | When you later interact with a DB, use parameterised queries / ORM; never concatenate raw strings. |
| **Logging** | Swap `console.log` for a structured logger (`pino`, `winston`) that can be shipped to ELK/Datadog. |
| **Secret management** | Store API keys, DB passwords, JWT secrets in environment variables or a secret manager (AWS Secrets Manager, HashiCorp Vault). |
| **Static analysis** | Add `eslint` with the `security` plugin (`eslint-plugin-security`) to catch common pitfalls. |
| **Testing** | Write unit & integration tests for each route; include tests for invalid payloads to ensure validation works. |
| **Health checks** | Expand `/health` to also verify DB/Redis connectivity (`/ready` vs `/live`). |
| **Rate‑limit per endpoint** | Some endpoints (login, password reset) may need stricter limits than generic ones. |
| **Content length** | Consider adding `app.use((req, res, next) => { if (req.headers['content‑length'] > 1048576) return res.status(413).end(); next(); });` to reject overly large bodies before parsing. |

---

## 4. How to integrate the changes

1. **Install the new dependencies**

   ```bash
   npm install helmet express-rate-limit celebrate dotenv express-async-handler morgan
   # optional (if you want a more powerful logger later)
   # npm install pino
   ```

2. **Create a `.env`** (add to `.gitignore`)

   ```
   PORT=3000
   NODE_ENV=development   # change to "production" on live
   ```

3. **Replace the current `app.js`** with the refactored version above (or copy the parts you need).  
   Keep the export at the bottom for any existing tests.

4. **Run your tests again** (or just start the server) to verify nothing broke:

   ```bash
   npm start   # or node app.js
   curl http://localhost:3000/health
   ```

5. **Add more routes** following the **validated route pattern** (celebrate → asyncHandler → ok response).  

