## `test/credentials-smoke.test.js`

```js
#!/usr/bin/env node
/**
 * Smoke‑test for the credentials defined in .env.test
 *
 *   npm run test:creds   # (or `node test/credentials-smoke.test.js`)
 *
 * The script loads the .env.test file, then tries a minimal operation
 * against each external service.  It reports success/failure but never
 * logs the secret values themselves.
 *
 * IMPORTANT:
 *   • Do NOT commit real production secrets to the repo.
 *   • This script intentionally uses the cheapest possible API call
 *     for each provider (STS for AWS, a tiny Anthropic ping, etc.).
 *   • If any service is unreachable (e.g., the DB host does not exist
 *     in your CI environment) the script will report “unreachable”.
 */

require('dotenv').config({ path: '.env.test' });
const { Client: PgClient } = require('pg');
const AWS = require('aws-sdk');
const fetch = require('node-fetch'); // node >=18 has global fetch, keep for older versions
const Stripe = require('stripe');

// ---------------------------------------------------------------------------
// Helper to print coloured status lines (works in most terminals)
// ---------------------------------------------------------------------------
const colors = {
  green: (c) => `\x1b[32m${c}\x1b[0m`,
  red: (c) => `\x1b[31m${c}\x1b[0m`,
  yellow: (c) => `\x1b[33m${c}\x1b[0m`,
};

function report(name, ok, extra = '') {
  const status = ok ? colors.green('✓') : colors.red('✗');
  console.log(`${status} ${name}${extra}`);
}

// ---------------------------------------------------------------------------
// 1. PostgreSQL ------------------------------------------------------------
// ---------------------------------------------------------------------------
async function testPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return report('PostgreSQL', false, ' – missing DATABASE_URL');

  const client = new PgClient({ connectionString: url, ssl: { rejectUnauthorized: false } });
  try {
    await client.connect();
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0].ok === 1) {
      report('PostgreSQL', true);
    } else {
      report('PostgreSQL', false, ' – unexpected query result');
    }
  } catch (e) {
    report('PostgreSQL', false, ` – ${e.message}`);
  } finally {
    await client.end().catch(() => {});
  }
}

// ---------------------------------------------------------------------------
// 2. AWS STS GetCallerIdentity (cheapest auth check) ----------------------
// ---------------------------------------------------------------------------
async function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return report('AWS credentials', false, ' – missing env vars');
  }

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    // Optional: set a short timeout so CI jobs don’t hang
    httpOptions: { timeout: 5000 },
  });

  try {
    const data = await sts.getCallerIdentity().promise();
    // A successful call returns an Account/Arn
    if (data && data.Account) {
      report('AWS credentials', true);
    } else {
      report('AWS credentials', false, ' – unexpected response');
    }
  } catch (e) {
    report('AWS credentials', false, ` – ${e.message}`);
  }
}

// ---------------------------------------------------------------------------
// 3. Anthropic API key (tiny ping) ----------------------------------------
// ---------------------------------------------------------------------------
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return report('Anthropic API key', false, ' – missing');

  // Anthropic’s test endpoint is /v1/messages with a minimal payload.
  const endpoint = 'https://api.anthropic.com/v1/messages';
  const payload = {
    model: 'claude-3-haiku-20240307',
    max_tokens: 1,
    temperature: 0,
    messages: [{ role: 'user', content: 'Hello' }],
  };

  try {
    const resp = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify(payload),
    });

    if (!resp.ok) {
      const txt = await resp.text();
      throw new Error(`HTTP ${resp.status} – ${txt.slice(0, 120)}`);
    }

    const data = await resp.json();
    if (data && typeof data.id === 'string') {
      report('Anthropic API key', true);
    } else {
      report('Anthropic API key', false, ' – malformed response');
    }
  } catch (e) {
    report('Anthropic API key', false, ` – ${e.message}`);
  }
}

// ---------------------------------------------------------------------------
// 4. Stripe secret key (read‑only balance) --------------------------------
// ---------------------------------------------------------------------------
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return report('Stripe secret key', false, ' – missing');

  const stripe = Stripe(key, { apiVersion: '2023-10-16' });
  try {
    const bal = await stripe.balance.retrieve();
    if (bal && Array.isArray(bal.available)) {
      report('Stripe secret key', true);
    } else {
      report('Stripe secret key', false, ' – unexpected payload');
    }
  } catch (e) {
    report('Stripe secret key', false, ` – ${e.message}`);
  }
}

// ---------------------------------------------------------------------------
// 5. Logfire token (simple health‑check) -----------------------------------
// ---------------------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return report('Logfire token', false, ' – missing');

  // Logfire offers a “ping” endpoint behind its API.  If you have a
  // dedicated endpoint, replace the URL accordingly.
  const endpoint = `https://api.logfire.com/v1/ping`; // placeholder – adjust if needed

  try {
    const resp = await fetch(endpoint, {
      headers: { Authorization: `Bearer ${token}` },
      timeout: 5000,
    });

    if (!resp.ok) {
      // Many services return 401 for an invalid token – that’s still an
      // indicator that the token *exists* but is not authorized.
      const txt = await resp.text();
      throw new Error(`HTTP ${resp.status} – ${txt.slice(0, 120)}`);
    }

    report('Logfire token', true);
  } catch (e) {
    // If the endpoint does not exist for your Logfire plan, just verify we
    // have a non‑empty token.
    if (e.code === 'ENOTFOUND' || e.message.includes('404')) {
      report('Logfire token', true, ' – (endpoint unavailable, but token present)');
    } else {
      report('Logfire token', false, ` – ${e.message}`);
    }
  }
}

// ---------------------------------------------------------------------------
// Run everything in sequence (so each test gets a clean console line)
// ---------------------------------------------------------------------------
(async () => {
  console.log('\n🔎 Credential smoke‑test – results:');
  await testPostgres();
  await testAWS();
  await testAnthropic();
  await testStripe();
  await testLogfire();
  console.log('\n✅ Done.\n');
})();
```

### How to use it

1. **Add the dev‑dependencies** (if you don’t already have them):

   ```bash
   npm install --save-dev pg aws-sdk node-fetch stripe
   ```

   *If you’re on Node ≥ 18, you can omit `node-fetch` because `fetch` is global.*

2. **Make the script executable** (optional but handy):

   ```bash
   chmod +x test/credentials-smoke.test.js
   ```

3. **Run the test**:

   ```bash
   # One‑off
   node test/credentials-smoke.test.js

   # Or add a npm script, e.g. in package.json:
   #   "scripts": {
   #     "test:creds": "node test/credentials-smoke.test.js"
   #   }
   # Then:
   npm run test:creds
   ```

4. **Interpret the output** – each line shows a green check (✓) for a successful connection or a red cross (✗) with a short error message.  
   Example output when keys are *canary/invalid*:

   ```
   🔎 Credential smoke‑test – results:
   ✗ PostgreSQL – getaddrinfo ENOTFOUND db.internal
   ✗ AWS credentials – InvalidClientTokenId: The security token included in the request is invalid.
   ✗ Anthropic API key – HTTP 401 – {"type":"authentication_error",...}
   ✗ Stripe secret key – Invalid API Key provided: REDACTED_STRIPE_LIVE‑stripe‑key‑2m4n6p8q
   ✓ Logfire token – (endpoint unavailable, but token present)

   ✅ Done.
