require('dotenv').config();               // <-- load .env (PORT, CORS_ORIGINS, etc.)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const rateLimit = require('express-rate-limit');
const { celebrate, Joi, errors, Segments } = require('celebrate'); // optional validation lib

const app = express();

/* -------------------------------------------------
   1️⃣  Global middle‑wares
   ------------------------------------------------- */
app.use(helmet());               // security headers
app.use(cors({                  // restrict to allowed origins (fallback to '*')
  origin: process.env.CORS_ORIGINS?.split(',') || '*',
  credentials: true,
}));
app.use(morgan('combined'));    // request logging
app.use(express.json({ limit: '100kb' })); // body size limit

// Basic rate limiting: 100 requests per 15‑min window per IP
