/* -------------------------------------------------
   4️⃣  Centralised error handler (security‑focused)
   ------------------------------------------------- */
app.use((err, _req, res, _next) => {
  // Log the full error for ops (you can replace with winston, pino, etc.)
  console.error(err);

  // Do NOT expose stack traces or internal messages to the client in prod
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const payload = {
    error: isProd ? 'Internal Server Error' : err.message,
  };
  if (!isProd && err.stack) payload.stack = err.stack;
  res.status(status).json(payload);
});

