    const { rows } = await client.query('SELECT version()');
    record('DATABASE_URL', true, rows[0].version);
  } catch (err) {
    record('DATABASE_URL', false, err.message);
  } finally {
    await client.end().catch(() => {}); // ignore end errors
  }
}

