    }
  } catch (err) {
    // If the endpoint is unknown, just treat connection failures as “cannot verify”
    record('LOGFIRE_TOKEN', false, err.message);
  }
}

/* ---------- 5️⃣ AWS CREDENTIALS ---------- */
async function checkAws() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKey || !secretKey) {
    record('AWS credentials', false, 'missing one or both keys');
    return;
  }

  const sts = new STSClient({
    region: 'us-east-1',
    credentials: { accessKeyId: accessKey, secretAccessKey: secretKey },
    requestHandler: new (require('@aws-sdk/node-http-handler').NodeHttpHandler)(),
  });

  try {
    const cmd = new GetCallerIdentityCommand({});
    const data = await sts.send(cmd);
    record('AWS credentials', true, `ARN ${data.Arn}`);
  } catch (err) {
    record('AWS credentials', false, err.message);
  }
}

/* ---------- Main runner ---------- */
(async () => {
  console.log('🔎 Starting credential verification…\n');

  await Promise.all([
    checkDatabase(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
    checkAws(),
  ]);

  console.log('\n📝 Summary:');
  const failures = results.filter(r => !r.passed);
  console.log(`  Total checks : ${results.length}`);
  console.log(`  Passed       : ${results.length - failures.length}`);
  console.log(`  Failed       : ${failures.length}`);

  // Exit code tells CI pipelines whether everything is OK
  process.exit(failures.length ? 1 : 0);
})();
```

