require('dotenv').config({ path: '.env.test' }); // <-- change path if you use .env
const { Client } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const fetch = require('node-fetch');

// -------------------------------------------------------------------------
// Helper – pretty‑print result
// -------------------------------------------------------------------------
function logResult(name, ok, details = '') {
  const status = ok ? '\x1b[32mOK\x1b[0m' : '\x1b[31mFAIL\x1b[0m';
  console.log(`[${status}] ${name}${details ? ` – ${details}` : ''}`);
}

// -------------------------------------------------------------------------
// 1️⃣  PostgreSQL check
// -------------------------------------------------------------------------
async function checkPostgres() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    logResult('PostgreSQL', false, 'DATABASE_URL not defined');
    return;
  }

  const client = new Client({ connectionString: dbUrl });

  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res && res.rowCount === 1) {
      logResult('PostgreSQL', true);
    } else {
      logResult('PostgreSQL', false, 'Unexpected query result');
    }
  } catch (err) {
    logResult('PostgreSQL', false, err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

// -------------------------------------------------------------------------
// 2️⃣  AWS STS GetCallerIdentity
// -------------------------------------------------------------------------
async function checkAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    logResult('AWS STS', false, 'Missing ACCESS_KEY_ID or SECRET_ACCESS_KEY');
    return;
  }

  const sts = new STSClient({
    credentials: {
      accessKeyId: AWS_ACCESS_KEY_ID,
      secretAccessKey: AWS_SECRET_ACCESS_KEY,
    },
    // Use a short timeout so the script finishes quickly if the credentials are bad
    requestHandler: undefined, // default handler
  });

  try {
    const cmd = new GetCallerIdentityCommand({});
    const data = await sts.send(cmd);
    logResult('AWS STS', true, `Account: ${data.Account}`);
  } catch (err) {
    // AWS SDK errors have a `.name` and `.message` we can surface
    logResult('AWS STS', false, err.message);
  }
}

