    if (resp.ok) {
      const data = await resp.json();
      logResult('Anthropic', true, `${data.models?.length || 0} models`);
    } else {
      const txt = await resp.text();
      logResult('Anthropic', false, `${resp.status} ${resp.statusText}: ${txt}`);
    }
  } catch (err) {
    logResult('Anthropic', false, err.message);
  }
}

// -------------------------------------------------------------------------
// 4️⃣  Stripe – attempt to list 1 charge (requires secret key)
// -------------------------------------------------------------------------
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    logResult('Stripe', false, 'STRIPE_SECRET_KEY not defined');
    return;
  }

