      const data = await resp.json();
      logResult('Stripe', true, `${data.data?.length || 0} charge(s) returned`);
    } else {
      const txt = await resp.text();
      logResult('Stripe', false, `${resp.status} ${resp.statusText}: ${txt}`);
    }
  } catch (err) {
    logResult('Stripe', false, err.message);
  }
}

// -------------------------------------------------------------------------
// 5️⃣  Logfire – simple health ping (if they expose one)
// -------------------------------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    logResult('Logfire', false, 'LOGFIRE_TOKEN not defined');
    return;
  }

  // Logfire (Logfire.io) does not have a public health endpoint; we’ll just
