```

### 3.2  Example middleware with Joi  

```js
const Joi = require('joi');

// Generic validation wrapper
function validate(schema) {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, {
      abortEarly: false,
      allowUnknown: false,   // reject unexpected fields
      stripUnknown: true,    // remove them if you wish
    });

    if (error) {
      // Turn validation errors into a 400 response
      return res.status(400).json({ error: error.details.map(d => d.message) });
    }

    // Overwrite req.body with the sanitized value
    req.body = value;
    next();
  };
}
```

*Usage example for a future POST endpoint*:

```js
