 *   • Anthropic    – GET /v1/health
 *   • Stripe       – fetches account balance
 *   • Logfire      – posts a single test event
 *
 * Usage:
 *   $ node test_credentials.js   # from the repository root
 *
 * NOTE:
 *   * The script never writes any secret to stdout – only success / error flags.
 *   * If a service is unreachable from your network the script will report “unreachable”.
 *   * This script is **intended for local/dev use only**; do not commit it to a public repo.
 */

require('dotenv').config({ path: '.env.test' }); // <-- load test env file

const { Client: PgClient } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const fetch = require('node-fetch'); // Node >=18 has global fetch, but keep it explicit for older versions
const Stripe = require('stripe');
const https = require('https');

/* ------------------------------------------------------------------ *
 *  Helper to print a nicely‑formatted line
 * ------------------------------------------------------------------ */
function logResult(service, ok, extra = '') {
  const status = ok ? '✅ OK' : '❌ FAIL';
  console.log(`[${service}] ${status}${extra ? ' – ' + extra : ''}`);
}

/* ------------------------------------------------------------------ *
 *  1️⃣ PostgreSQL
 * ------------------------------------------------------------------ */
async function testPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return logResult('Postgres', false, 'VARIABLE MISSING');

  const client = new PgClient({ connectionString: url });
  try {
    await client.connect();
    const res = await client.query('SELECT 1 AS ok');
    if (res.rows[0]?.ok === 1) {
      logResult('Postgres', true);
    } else {
      logResult('Postgres', false, 'UNEXPECTED RESPONSE');
    }
  } catch (err) {
    logResult('Postgres', false, err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

/* ------------------------------------------------------------------ *
 *  2️⃣ AWS – STS GetCallerIdentity
 * ------------------------------------------------------------------ */
async function testAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return logResult('AWS', false, 'VARIABLE(S) MISSING');
  }

  const sts = new STSClient({
    credentials: {
      accessKeyId: AWS_ACCESS_KEY_ID,
      secretAccessKey: AWS_SECRET_ACCESS_KEY,
    },
  });

  try {
    const cmd = new GetCallerIdentityCommand({});
    const data = await sts.send(cmd);
    // If we got a response we know the keys are valid
    logResult('AWS', true, `Arn=${data.Arn}`);
  } catch (err) {
    logResult('AWS', false, err.message);
  }
}

/* ------------------------------------------------------------------ *
 *  3️⃣ Anthropic – health endpoint
 * ------------------------------------------------------------------ */
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return logResult('Anthropic', false, 'VARIABLE MISSING');

  try {
    const resp = await fetch('https://api.anthropic.com/v1/health', {
      method: 'GET',
      headers: {
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
      },
    });

    if (!resp.ok) {
      return logResult('Anthropic', false, `${resp.status} ${resp.statusText}`);
    }

    const json = await resp.json();
    // The health endpoint returns {status: "ok"} (or similar)
    if (json?.status?.toLowerCase?.() === 'ok') {
      logResult('Anthropic', true);
    } else {
      logResult('Anthropic', false, JSON.stringify(json));
    }
  } catch (err) {
    logResult('Anthropic', false, err.message);
  }
}

/* ------------------------------------------------------------------ *
 *  4️⃣ Stripe – retrieve balance (read‑only)
 * ------------------------------------------------------------------ */
async function testStripe() {
  const secret = process.env.STRIPE_SECRET_KEY;
  if (!secret) return logResult('Stripe', false, 'VARIABLE MISSING');

  const stripe = Stripe(secret, { apiVersion: '2023-10-16' });

  try {
    const bal = await stripe.balance.retrieve();
    // If we have a positive amount the key works
    if (bal?.available?.length) {
      logResult('Stripe', true);
    } else {
      logResult('Stripe', false, 'EMPTY BALANCE');
    }
  } catch (err) {
    // Stripe errors have .raw && .raw.message
    const msg = err?.raw?.message ?? err.message ?? 'UNKNOWN';
    logResult('Stripe', false, msg);
  }
}

/* ------------------------------------------------------------------ *
 *  5️⃣ Logfire – send a test event (write‑only but cheap)
 * ------------------------------------------------------------------ */
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return logResult('Logfire', false, 'VARIABLE MISSING');

  const payload = {
    level: 'info',
    message: 'credential‑validation‑test',
    timestamp: new Date().toISOString(),
  };

  // Logfire expects JSON body + Bearer token auth
  const options = {
    method: 'POST',
    hostname: 'api.logfire.dev',
    path: '/v1/event',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
    },
  };

  const req = https.request(options, (res) => {
    let data = '';
    res.on('data', (chunk) => (data += chunk));
    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        logResult('Logfire', true);
      } else {
        logResult('Logfire', false, `${res.statusCode} ${data}`);
      }
    });
  });

  req.on('error', (e) => logResult('Logfire', false, e.message));
  req.write(JSON.stringify(payload));
  req.end();
}

/* ------------------------------------------------------------------ *
 *  Run all tests (in parallel where possible)
 * ------------------------------------------------------------------ */
(async () => {
  console.log('🔍 Starting credential sanity‑check ...\n');

  // PostgreSQL is I/O‑blocking, run it first so we can close the client early
  await testPostgres();

  // The remaining services can be checked concurrently
  await Promise.all([
    testAWS(),
    testAnthropic(),
    testStripe(),
    testLogfire(),
  ]);

  console.log('\n✅ Done.');
})();
```

### How to use it

1. **Install the only runtime dependencies** required for the checks:

   ```bash
   npm install pg @aws-sdk/client-sts node-fetch stripe
   ```

   *(If you’re on Node ≥ 18 the global `fetch` is already available; the `node-fetch` import is harmless and ensures compatibility with older versions.)*

2. **Run the script** from the repo root:

