```js
// ---------------------------------------------------------------
// verify-credentials.js
// ---------------------------------------------------------------
// Loads .env.test, attempts a light‑weight connection to each
// external service, and prints a PASS / FAIL table.
// ---------------------------------------------------------------

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const AWS = require('aws-sdk');
const fetch = require('node-fetch');

// -------------------------------------------------------------------
// Helper: pretty result printer
// -------------------------------------------------------------------
function result(status, message = '') {
  return { status: status ? 'PASS' : 'FAIL', message };
}

// -------------------------------------------------------------------
// 1️⃣ PostgreSQL check
// -------------------------------------------------------------------
async function checkPostgres() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) return result(false, 'DATABASE_URL not defined');

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    await client.query('SELECT 1'); // simple no‑op query
    await client.end();
    return result(true);
  } catch (err) {
    return result(false, err.message);
  }
}

// -------------------------------------------------------------------
// 2️⃣ AWS STS GetCallerIdentity (cheapest AWS API call)
// -------------------------------------------------------------------
async function checkAws() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return result(false, 'AWS keys missing');
  }

  const sts = new AWS.STS({
    accessKeyId: AWS_ACCESS_KEY_ID,
    secretAccessKey: AWS_SECRET_ACCESS_KEY,
    // Optional: set a short timeout to avoid hanging if the network is blocked
    httpOptions: { timeout: 5000 },
  });

  try {
    await sts.getCallerIdentity().promise();
    return result(true);
  } catch (err) {
    // Most common: InvalidClientTokenId / SignatureDoesNotMatch
    return result(false, err.message);
  }
}

// -------------------------------------------------------------------
// 3️⃣ Anthropic API key sanity check
// -------------------------------------------------------------------
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return result(false, 'ANTHROPIC_API_KEY missing');

  const url = 'https://api.anthropic.com/v1/messages';
  const body = {
    model: 'claude-3-haiku-20240307', // any model that exists for you
    max_tokens: 1,
    temperature: 0,
    messages: [{ role: 'user', content: 'Ping' }],
  };

  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        'x-api-key': key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify(body),
    });

    // 200 → key works; 401/403 → invalid; any other → treat as failure
    if (resp.ok) return result(true);
    return result(false, `HTTP ${resp.status}`);
  } catch (err) {
    return result(false, err.message);
  }
}

// -------------------------------------------------------------------
// 4️⃣ Stripe secret key check (list 1 customer – safe, read‑only)
// -------------------------------------------------------------------
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return result(false, 'STRIPE_SECRET_KEY missing');

  const url = 'https://api.stripe.com/v1/customers?limit=1';
  try {
    const resp = await fetch(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${key}`,
      },
    });
    if (resp.ok) return result(true);
    return result(false, `HTTP ${resp.status}`);
  } catch (err) {
    return result(false, err.message);
  }
}

// -------------------------------------------------------------------
// 5️⃣ Logfire token sanity (HEAD request to ingestion endpoint)
// -------------------------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) return result(false, 'LOGFIRE_TOKEN missing');

  const url = 'https://logfire.dev/api/v1/ingest';
  try {
    const resp = await fetch(url, {
      method: 'HEAD',
      headers: { Authorization: `Bearer ${token}` },
    });
    // Logfire returns 401 for an invalid token, 200 for a good one.
    // Treat both as “we could reach the service & token format is accepted”.
    if (resp.status === 200 || resp.status === 401) return result(true);
    return result(false, `HTTP ${resp.status}`);
  } catch (err) {
    return result(false, err.message);
  }
}

// -------------------------------------------------------------------
// Main driver – run all checks in parallel and display a table
// -------------------------------------------------------------------
(async () => {
  console.log('\n🔍 Verifying external credentials …\n');

  const checks = await Promise.all([
    checkPostgres(),
    checkAws(),
    checkAnthropic(),
    checkStripe(),
    checkLogfire(),
