// ---------- 3️⃣ Central error handler ----------
app.use((err, req, res, next) => {
  // Log the full error (stack) on the server side
  console.error(err);

  // Do NOT expose stack traces or internal messages to the client.
  const status = err.status || 500;
  const response = {
    error:
      status === 500
        ? 'Internal Server Error'
        : err.message || 'Unexpected error',
  };
  res.status(status).json(response);
});

// ---------- 4️⃣ Export the app (no .listen here) ----------
