// ---------- 5️⃣ Separate start script (optional) ----------
if (require.main === module) {
  // When the file is executed directly (`node app.js`) we start the server.
  const PORT = process.env.PORT || 3000;
  const server = app.listen(PORT, () => {
    console.info(`🚀 Server listening on http://localhost:${PORT}`);
  });

  // Graceful shutdown on SIGTERM / SIGINT
  const shutdown = () => {
    console.info('\nGracefully shutting down...');
    server.close(() => {
      console.info('Server closed. Exiting process.');
      process.exit(0);
    });
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

// ---------- 6️⃣ Process‑level error handling ----------
process.on('unhandledRejection', (reason, promise) => {
  console.error('⚠️ Unhandled Rejection at:', promise, 'reason:', reason);
  // Depending on severity, you may decide to terminate the process.
});
process.on('uncaughtException', err => {
  console.error('💥 Uncaught Exception:', err);
  process.exit(1); // crash the process – a crashed process is safer than a corrupted one.
});
