// verify-creds.js
// ------------------------------------------------------------
// Small utility that checks the env vars defined in .env.test
// (or any other env file) for basic connectivity / validity.
// ------------------------------------------------------------

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const https = require('https');
const { URL } = require('url');

// Helper: simple GET request returning JSON (or throwing)
function httpsGetJson(url, headers = {}) {
  return new Promise((resolve, reject) => {
    const opts = new URL(url);
    opts.headers = headers;
    https
      .get(opts, res => {
        let data = '';
        res.on('data', chunk => (data += chunk));
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            try {
              resolve(JSON.parse(data));
            } catch (e) {
              reject(new Error('Invalid JSON response'));
            }
          } else {
            reject(
              new Error(`HTTP ${res.statusCode} – ${res.statusMessage}`)
            );
          }
        });
      })
      .on('error', reject);
  });
}

// ------------------------------------------------------------------
// 1️⃣ Check PostgreSQL connection (DATABASE_URL)
// ------------------------------------------------------------------
async function checkDatabase() {
  const uri = process.env.DATABASE_URL;
  if (!uri) throw new Error('DATABASE_URL not set');

  const client = new Client({ connectionString: uri });
  await client.connect();
  const res = await client.query('SELECT 1 AS ok');
  await client.end();

  if (res.rows[0].ok !== 1) {
    throw new Error('Unexpected query result');
  }
  return 'OK';
}

// ------------------------------------------------------------------
// 2️⃣ AWS credentials – use STS GetCallerIdentity (no charges)
// ------------------------------------------------------------------
async function checkAws() {
  const id = process.env.AWS_ACCESS_KEY_ID;
  const secret = process.env.AWS_SECRET_ACCESS_KEY;
  if (!id || !secret) throw new Error('AWS keys missing');

  // Build a signed request manually (simplified) using AWS SDK v3 would be easier,
  // but to keep the script lightweight we just call the public “whoami” endpoint
  // that accepts the keys as query parameters for test purposes.
  // NOTE: In a real environment you’d use @aws-sdk/client-sts.
  const url = `https://sts.amazonaws.com/?Action=GetCallerIdentity&Version=2011-06-15`;
  // The SDK would sign the request; here we only verify that the keys exist.
  // If they’re invalid, AWS will return a 403 – we treat any 2xx as success.
  try {
    await httpsGetJson(url, {
      'x-amz-content-sha256': 'UNSIGNED-PAYLOAD',
      // The following headers are placeholders; the real test should use the SDK.
      // This minimal check is just a placeholder so the script runs without extra deps.
    });
    return 'OK (request succeeded – keys likely valid)';
  } catch (e) {
    // AWS returns XML on error, but the request will still throw.
    return `FAIL – ${e.message}`;
  }
}

// ------------------------------------------------------------------
// 3️⃣ Anthropic API key – call the models list endpoint
// ------------------------------------------------------------------
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error('ANTHROPIC_API_KEY missing');

  const url = 'https://api.anthropic.com/v1/models';
  const headers = { 'x-api-key': key, 'anthropic-version': '2023-06-01' };
  try {
    const json = await httpsGetJson(url, headers);
    // Expect an array of model identifiers
    if (Array.isArray(json.models) && json.models.length) {
      return `OK – ${json.models.length} models returned`;
    }
    return 'OK – response received, but unexpected shape';
  } catch (e) {
    return `FAIL – ${e.message}`;
  }
}

// ------------------------------------------------------------------
// 4️⃣ Stripe secret key – retrieve account details (no charges)
// ------------------------------------------------------------------
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY missing');

  const url = 'https://api.stripe.com/v1/account';
  const auth = Buffer.from(`${key}:`).toString('base64');
  try {
    const json = await httpsGetJson(url, {
      Authorization: `Basic ${auth}`,
    });
    return `OK – account ${json.id}`;
  } catch (e) {
    return `FAIL – ${e.message}`;
  }
}

// ------------------------------------------------------------------
// 5️⃣ Logfire token – health endpoint (if Logfire provides one)
// ------------------------------------------------------------------
async function checkLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) throw new Error('LOGFIRE_TOKEN missing');

  // Assuming Logfire exposes a health endpoint of the form:
  const url = `https://logfire.io/api/v1/health?token=${token}`;
  try {
    const json = await httpsGetJson(url);
    return json.status === 'ok' ? 'OK – service healthy' : 'FAIL – unhealthy';
  } catch (e) {
    return `FAIL – ${e.message}`;
  }
}

// ------------------------------------------------------------------
// Run all checks & print a table
// ------------------------------------------------------------------
(async () => {
  const checks = [
    { name: 'PostgreSQL (DATABASE_URL)', fn: checkDatabase },
    { name: 'AWS STS (AWS_ACCESS_KEY_ID/SECRET)', fn: checkAws },
    { name: 'Anthropic (ANTHROPIC_API_KEY)', fn: checkAnthropic },
    { name: 'Stripe (STRIPE_SECRET_KEY)', fn: checkStripe },
    { name: 'Logfire (LOGFIRE_TOKEN)', fn: checkLogfire },
  ];

  console.log('\n=== Credential Validation Report ===\n');

  for (const { name, fn } of checks) {
    try {
      const result = await fn();
      console.log(`${name.padEnd(45)} : ✅ ${result}`);
    } catch (err) {
      console.log(`${name.padEnd(45)} : ❌ ${err.message}`);
    }
  }

  console.log('\nDone.\n');
})();
```

