// verify-creds.js
// ---------------------------------------------------------------
// Load environment variables from .env.test (or from process.env)
// ---------------------------------------------------------------
require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const fetch = require('node-fetch');
const Stripe = require('stripe');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');

// Helper to print a nice status line
function logResult(service, ok, details = '') {
  const status = ok ? '✅ SUCCESS' : '❌ FAILURE';
  console.log(`[${service}] ${status}${details ? ' – ' + details : ''}`);
}

// ------------------------------------------------------------------
// 1️⃣  PostgreSQL test
// ------------------------------------------------------------------
async function testPostgres() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.warn('DATABASE_URL not set – skipping Postgres test.');
    return;
  }

  const client = new Client({ connectionString: dbUrl });
  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res && res.rowCount === 1) {
      logResult('Postgres', true);
    } else {
      logResult('Postgres', false, 'unexpected query result');
    }
  } catch (err) {
    logResult('Postgres', false, err.message);
  } finally {
    await client.end();
  }
}

// ------------------------------------------------------------------
// 2️⃣  Anthropic API test
// ------------------------------------------------------------------
async function testAnthropic() {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    console.warn('ANTHROPIC_API_KEY not set – skipping Anthropic test.');
    return;
  }

  const url = 'https://api.anthropic.com/v1/models';
  try {
    const resp = await fetch(url, {
      method: 'GET',
      headers: {
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
    });

    if (resp.ok) {
      logResult('Anthropic', true);
    } else {
      const body = await resp.text();
      logResult('Anthropic', false, `HTTP ${resp.status} – ${body}`);
    }
  } catch (err) {
    logResult('Anthropic', false, err.message);
  }
}

// ------------------------------------------------------------------
// 3️⃣  Stripe test
// ------------------------------------------------------------------
async function testStripe() {
  const secretKey = process.env.STRIPE_SECRET_KEY;
  if (!secretKey) {
    console.warn('STRIPE_SECRET_KEY not set – skipping Stripe test.');
    return;
  }

  const stripe = Stripe(secretKey, { apiVersion: '2022-11-15' });

  try {
    // A “list readers” call is cheap and read‑only.
    const readers = await stripe.terminal.readers.list({ limit: 1 });
    // If we got here, the key is accepted.
    logResult('Stripe', true);
  } catch (err) {
    // Stripe SDK provides a nice `type` field.
    const msg = err && err.type ? `${err.type}: ${err.message}` : err.message;
    logResult('Stripe', false, msg);
  }
}

// ------------------------------------------------------------------
// 4️⃣  AWS STS test
// ------------------------------------------------------------------
async function testAWS() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  if (!accessKey || !secretKey) {
    console.warn('AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY not set – skipping AWS test.');
    return;
  }

  const sts = new STSClient({
    credentials: { accessKeyId: accessKey, secretAccessKey: secretKey },
    region: 'us-east-1', // any region works for STS
  });

  try {
    const cmd = new GetCallerIdentityCommand({});
    const data = await sts.send(cmd);
    logResult('AWS STS', true, `ARN=${data.Arn}`);
  } catch (err) {
    const msg = err && err.message ? err.message : JSON.stringify(err);
    logResult('AWS STS', false, msg);
  }
}

// ------------------------------------------------------------------
// 5️⃣  Logfire test
// ------------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    console.warn('LOGFIRE_TOKEN not set – skipping Logfire test.');
    return;
  }

  const url = 'https://logfire.io/api/v1/telemetry';
  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      // sending an empty (but valid) payload – the service just acknowledges receipt
      body: JSON.stringify({ events: [] }),
    });

    if (resp.ok) {
      logResult('Logfire', true);
    } else {
      const body = await resp.text();
      logResult('Logfire', false, `HTTP ${resp.status} – ${body}`);
    }
  } catch (err) {
    logResult('Logfire', false, err.message);
  }
}

// ------------------------------------------------------------------
// Run everything sequentially (so output order is predictable)
// ------------------------------------------------------------------
(async () => {
  console.log('=== Starting credential verification ===\n');

  await testPostgres();
  await testAnthropic();
  await testStripe();
  await testAWS();
  await testLogfire();

  console.log('\n=== Done ===');
})();
```

