require('dotenv').config({ path: '.env.test' });

const { Client: PgClient } = require('pg');
const { STSClient, GetCallerIdentityCommand } = require('@aws-sdk/client-sts');
const fetch = require('node-fetch'); // remove if using Node >=18 with native fetch
const Stripe = require('stripe');

// ---------------------------------------------------------------------------
// Helper to print a consistent line
function logResult(service, ok, details) {
  const status = ok ? '✅ SUCCESS' : '❌ FAILURE';
  console.log(`[${service}] ${status}: ${details}`);
}

// ---------------------------------------------------------------------------
// 1️⃣ PostgreSQL -------------------------------------------------------------
async function checkPostgres() {
  const url = process.env.DATABASE_URL;
  if (!url) return logResult('Postgres', false, 'DATABASE_URL not set');

  const client = new PgClient({ connectionString: url });
  try {
    await client.connect();
    const res = await client.query('SELECT 1');
    if (res.rowCount === 1) {
      logResult('Postgres', true, 'Connected and query succeeded');
    } else {
      logResult('Postgres', false, 'Unexpected query result');
    }
  } catch (err) {
    logResult('Postgres', false, err.message);
  } finally {
    await client.end().catch(() => {});
  }
}

// ---------------------------------------------------------------------------
// 2️⃣ AWS STS ---------------------------------------------------------------
async function checkAWS() {
  const { AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    return logResult('AWS', false, 'Missing AWS credentials');
  }

  const sts = new STSClient({
    credentials: {
      accessKeyId: AWS_ACCESS_KEY_ID,
      secretAccessKey: AWS_SECRET_ACCESS_KEY,
    },
    // you can optionally set a region; STS works in any region, so us-east-1 is fine.
    region: 'us-east-1',
  });

  try {
    const cmd = new GetCallerIdentityCommand({});
    const data = await sts.send(cmd);
    logResult('AWS', true, `ARN: ${data.Arn}`);
  } catch (err) {
    logResult('AWS', false, err.message);
  }
}

