// 3️⃣ Anthropic -------------------------------------------------------------
async function checkAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return logResult('Anthropic', false, 'ANTHROPIC_API_KEY not set');

  // Minimal request – 1‑token prompt, 1‑token response
