      method: 'POST',
      headers: {
        'x-api-key': key,
        'content-type': 'application/json',
        // Anthropic requires this header for versioning
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify(body),
    });

    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    logResult('Anthropic', true, `Message ID: ${data.id}`);
  } catch (err) {
    logResult('Anthropic', false, err.message);
  }
}

// ---------------------------------------------------------------------------
// 4️⃣ Stripe -----------------------------------------------------------------
async function checkStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) return logResult('Stripe', false, 'STRIPE_SECRET_KEY not set');

  const stripe = Stripe(key, { apiVersion: '2022-11-15' });

