```js
/**
 * verify‑credentials.js
 *
 * Quick sanity‑check for environment‑dependent secrets.
 * • Attempts a DB connection using DATABASE_URL
 * • Calls trivial endpoints for AWS, Anthropic, Stripe, Logfire
 *
 * Run with:  node test/verify-credentials.js
 *
 * Exit code:
 *   0 – all checks succeeded
 *   1 – one or more checks failed
 */

require('dotenv').config({ path: '.env.test' });

const { Client } = require('pg');
const axios = require('axios');

// ---------------------------------------------------------------------
// Helper to print a consistent result line
// ---------------------------------------------------------------------
function report(name, ok, details = '') {
  const status = ok ? '✅ SUCCESS' : '❌ FAILURE';
  console.log(`${status} – ${name}${details ? ` → ${details}` : ''}`);
}

// ---------------------------------------------------------------------
// 1️⃣ PostgreSQL connectivity test
// ---------------------------------------------------------------------
async function testPostgres() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    report('PostgreSQL', false, 'DATABASE_URL missing');
    return false;
  }

  const client = new Client({ connectionString: dbUrl });

  try {
    await client.connect();
    // Run a harmless query – ‘SELECT 1’ is supported by every PostgreSQL version
    const res = await client.query('SELECT 1 AS ok');
    const ok = res.rows[0]?.ok === 1;
    report('PostgreSQL', ok, ok ? '' : `unexpected result ${JSON.stringify(res.rows)}`);
    return ok;
  } catch (err) {
    // Most likely auth failure, network error, or SSL mis‑config
    report('PostgreSQL', false, err.message);
    return false;
  } finally {
    await client.end().catch(() => {});
  }
}

// ---------------------------------------------------------------------
// 2️⃣ AWS STS GetCallerIdentity – works with any valid IAM key pair
// ---------------------------------------------------------------------
async function testAws() {
  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKey || !secretKey) {
    report('AWS', false, 'keys missing');
    return false;
  }

  const aws = require('aws-sdk');
  const sts = new aws.STS({
    accessKeyId: accessKey,
    secretAccessKey: secretKey,
    // Minimal timeout – we only need a quick health check
    httpOptions: { timeout: 3000 },
  });

  try {
    const data = await sts.getCallerIdentity().promise();
    report('AWS', true, `ARN=${data.Arn}`);
    return true;
  } catch (err) {
    report('AWS', false, err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// 3️⃣ Anthropic “ping” – the API offers a GET /v1/health endpoint
// ---------------------------------------------------------------------
async function testAnthropic() {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    report('Anthropic', false, 'API key missing');
    return false;
  }

  try {
    const resp = await axios.get('https://api.anthropic.com/v1/health', {
      headers: { 'x-api-key': key },
      timeout: 3000,
    });
    const ok = resp.status === 200 && resp.data?.status === 'ok';
    report('Anthropic', ok, ok ? '' : `status=${resp.status}`);
    return ok;
  } catch (err) {
    report('Anthropic', false, err.response?.statusText || err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// 4️⃣ Stripe “balance” endpoint – requires a secret key
// ---------------------------------------------------------------------
async function testStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) {
    report('Stripe', false, 'secret key missing');
    return false;
  }

  try {
    const resp = await axios.get('https://api.stripe.com/v1/balance', {
      auth: { username: key, password: '' }, // Stripe uses basic auth with the secret as username
      timeout: 3000,
    });
    const ok = resp.status === 200 && resp.data?.object === 'balance';
    report('Stripe', ok, ok ? '' : `status=${resp.status}`);
    return ok;
  } catch (err) {
    report('Stripe', false, err.response?.statusText || err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// 5️⃣ Logfire “ping” – the public API accepts a GET to the token’s endpoint
// ---------------------------------------------------------------------
async function testLogfire() {
  const token = process.env.LOGFIRE_TOKEN;
  if (!token) {
    report('Logfire', false, 'token missing');
    return false;
  }

  // Logfire’s public ping endpoint is undocumented here; we’ll just try a GET
  // on the base URL with the token as a query param (most Logfire clients accept that)
  const url = `https://logfire.io/api/v1/ping?token=${encodeURIComponent(token)}`;

  try {
    const resp = await axios.get(url, { timeout: 3000 });
    const ok = resp.status === 200 && resp.data?.status === 'ok';
    report('Logfire', ok, ok ? '' : `status=${resp.status}`);
    return ok;
  } catch (err) {
    report('Logfire', false, err.response?.statusText || err.message);
    return false;
  }
}

// ---------------------------------------------------------------------
// Main runner
// ---------------------------------------------------------------------
(async () => {
  const checks = [
    testPostgres,
    testAws,
    testAnthropic,
    testStripe,
    testLogfire,
  ];

  const results = await Promise.all(checks.map(fn => fn()));
  const allOk = results.every(Boolean);

  console.log('\n=== SUMMARY ===');
  console.log(`All checks passed: ${allOk ? 'YES' : 'NO'}`);

  // Exit with a non‑zero code if any check failed – useful for CI pipelines
  process.exit(allOk ? 0 : 1);
})();
```

